4.questionText:
What does the following Java program print?

class Parent {
    int x = 10;
    Parent() { print(); }
    void print() { System.out.print(x + " "); }
}
class Child extends Parent {
    int x = 20;
    void print() { System.out.print(x + " "); }
}
public class Test {
    public static void main(String[] args) {
        new Child();
    }
}

What will be printed by the following Python program?

def repeat(num):
    def decorator(func):
        def wrapper(*args, **kwargs):
            val = 0
            for _ in range(num):
                val += func(*args, **kwargs)
            return val
        return wrapper
    return decorator

@repeat(3)
def compute(x):
    return x * 2

print(compute(4))

